WITH funded AS ({{FUNDED}}) SELECT b.pmid,COALESCE(SUM(CASE WHEN t.accept_time>='2026-01-01 00:00:00' AND (t.buy_amount>0 AND ((t.trade_type='wallet.recharge' AND t.extra IN ('by.online','by.offline')) OR (t.trade_type<>'wallet.recharge' AND t.extra='from.card'))) THEN t.buy_amount ELSE 0 END),0) ytd_inflow_before,
        SUM(CASE WHEN t.accept_time>='2026-01-01 00:00:00' AND (t.buy_amount>0 AND ((t.trade_type='wallet.recharge' AND t.extra IN ('by.online','by.offline')) OR (t.trade_type<>'wallet.recharge' AND t.extra='from.card'))) THEN 1 ELSE 0 END) ytd_inflow_transactions_before,
        MAX(CASE WHEN ((t.trade_type IN ('po.buy','po.sell','fund.buy','fund.sell','si.trade','plan.trade','wallet.redeem','wallet.quick.redeem','qszg.buy','qszg.sell','po.convert.buy','po.convert.redeem') AND (t.buy_amount>0 OR t.redeem_amount>0))) OR (t.buy_amount>0 AND ((t.trade_type='wallet.recharge' AND t.extra IN ('by.online','by.offline')) OR (t.trade_type<>'wallet.recharge' AND t.extra='from.card'))) THEN t.accept_time END) last_trade_before
        FROM funded b LEFT JOIN qm_meta.trade_detail t ON t.user_id=b.pmid AND t.canceled=0 AND t.accept_time<b.fb GROUP BY b.pmid
